/**
 * `token_claim`: make a prover or verifier from a URL serving a copy of
 * `target/xark/token-claim/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await TokenClaim.prover("/circuits/token_claim/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await TokenClaim.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const TokenClaim = new Circuit<TokenClaimInputs, TokenClaimPublicInputs, TokenClaimPublicValues, TokenClaimStructs>({
  name: "token_claim",
  schema,
  decodePublic,
  client: true,
  digest: "41f8cf4f8d4625284ec61bea304dc68b",
});

export type TokenClaimProver = Prover<TokenClaimInputs, TokenClaimPublicInputs, TokenClaimPublicValues, TokenClaimStructs>;
export type TokenClaimVerifier = Verifier<TokenClaimPublicInputs, TokenClaimPublicValues, TokenClaimStructs>;
export type TokenClaimProof = Proof<TokenClaimPublicValues>;

/** `Path`'s Rust functions (`#[input] impl Path`), run from `client.wasm`. */
export const Path = {
  /**
   * The path of the leaf after this one, once `leaf` is at this path: for the next
   * free leaf's path, the next free leaf's path after adding `leaf` to the list.
   * (A Rust client that holds the whole list uses [`list`], a `Tree`, instead.)
   */
  next(path: Path, leaf: FieldInput): PathValue {
    return decodePath(TokenClaim.call<Json<PathValue>>("Path.next", [path, leaf]));
  },
  /**
   * The root of the tree with `leaf` at this path. In a circuit this binds `index`
   * below 2^20, and `merkle_root` each of its bits to 0 or 1.
   */
  root(path: Path, leaf: FieldInput): Field {
    return new Field(TokenClaim.call<Json<Field>>("Path.root", [path, leaf]));
  },
  /**
   * The first leaf's path, in the empty list: every sibling is empty.
   */
  first(): PathValue {
    return decodePath(TokenClaim.call<Json<PathValue>>("Path.first", []));
  },
  /**
   * This path once `leaf` is at `later`, a later leaf's path: the subtree beside
   * this path that `leaf` lands in is the one sibling it changes.
   */
  update(path: Path, later: Path, leaf: FieldInput): PathValue {
    return decodePath(TokenClaim.call<Json<PathValue>>("Path.update", [path, later, leaf]));
  },
  /**
   * For the next free leaf's path, the root of the list so far: every leaf from
   * this one on is empty.
   */
  listRoot(path: Path): Field {
    return new Field(TokenClaim.call<Json<Field>>("Path.list_root", [path]));
  },
};

/** `Claim`'s Rust functions (`#[input] impl Claim`), run from `client.wasm`. */
export const Claim = {
  /**
   * The leaf the claim is in the list as: `Poseidon2(claimant.hi, claimant.lo,
   * amount)`.
   */
  leaf(claim: Claim): Field {
    return new Field(TokenClaim.call<Json<Field>>("Claim.leaf", [claim]));
  },
};

function decodePublic(v: Json<TokenClaimPublicValues>): TokenClaimPublicValues {
  return {
    root: new Field(v.root),
    claim: decodeClaim(v.claim),
  };
}

function decodeClaim(v: Json<ClaimValue>): ClaimValue {
  return new ClaimValue({
    claimant: v.claimant,
    amount: BigInt(v.amount),
  });
}

function decodePath(v: Json<PathValue>): PathValue {
  return new PathValue({
    index: v.index,
    siblings: v.siblings.map((x) => new Field(x)),
  });
}
